def contour(R,eps):
 w=np.geomspace(eps,R,10001)
 return np.concatenate([-1j*w[::-1],eps*np.exp(1j*np.linspace(-np.pi/2,np.pi/2,3001)),1j*w,R*np.exp(1j*np.linspace(np.pi/2,-np.pi/2,3001))])
def winding(fun,R,eps):
 v=1+fun(contour(R,eps));return -(np.unwrap(np.angle(v))[-1]-np.unwrap(np.angle(v))[0])/(2*np.pi)
for R,eps in [(1e3,1e-3),(1e4,1e-4)]:
 for k in [5,10]:
  n=winding(lambda s:k/(s*(s+1)*(s+2)),R,eps)
  roots=np.roots([1,3,2,k]);print('K,R,eps,Ncw,Z:',k,R,eps,n,sum(roots.real>1e-8))
  assert abs(n-(0 if k==5 else 2))<1e-8
 n=winding(lambda s:2/(s-1),R,eps);print('P=1, K=2, Ncw,Z:',n,1+n);assert abs(n+1)<1e-8
